import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { register } from "../apis/AuthApi";

function Register() {
  const navigate = useNavigate();

  const [form, setForm] = useState({
    name: "",
    email: "",
    password: "",
  });
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setForm({
      ...form,
      [e.target.name]: e.target.value,
    });
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      await register(form);
      alert("Register Success!");
      navigate("/login");
    } catch (error) {
      console.error("Register failed", error);
      if (error.response?.status === 409) {
        alert("A user with this email already exists.");
      } else {
        alert("Unable to register. Check your details and try again.");
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-indigo-900 via-black to-gray-900">

      <div className="w-full max-w-md bg-white/10 backdrop-blur-2xl border border-white/20 rounded-3xl p-10 text-white">

        <h1 className="text-3xl text-center font-bold">Create Account</h1>

        <form onSubmit={handleRegister} className="space-y-5 mt-8">

          <input
            type="text"
            name="name"
            placeholder="Name"
            value={form.name}
            onChange={handleChange}
            className="w-full px-4 py-3 rounded-xl bg-white/10 border border-white/20"
          />

          <input
            type="email"
            name="email"
            placeholder="Email"
            value={form.email}
            onChange={handleChange}
            className="w-full px-4 py-3 rounded-xl bg-white/10 border border-white/20"
          />

          <input
            type="password"
            name="password"
            placeholder="Password"
            value={form.password}
            onChange={handleChange}
            className="w-full px-4 py-3 rounded-xl bg-white/10 border border-white/20"
          />

          <button className="w-full py-3 rounded-xl bg-gradient-to-r from-purple-500 to-blue-500">
            Register
          </button>
        </form>

        <p className="text-center mt-6">
          Already have account?{" "}
          <span
            onClick={() => navigate("/login")}
            className="cursor-pointer font-bold"
          >
            Login
          </span>
        </p>
      </div>
    </div>
  );
}

export default Register;
